"""Combine validation gates and throughput into a migration recommendation."""
import json,statistics,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];out=ROOT/'concept_mapping/runs/pufferlib_map_validation'
parity=json.loads((out/'parity_report.json').read_text());world=json.loads((out/'world_report.json').read_text());resume=json.loads((out/'resume/report.json').read_text());encoder=json.loads((out/'encoder_check.json').read_text());reset=json.loads((out/'reset_report.json').read_text());timing=json.loads((out/'timing/results.json').read_text())
runs=timing['results'];failed=[r for r in parity['transition_cases'] if not r['transition_matches']]
warm=[statistics.median(r['metrics']['SPS'][2:-2]) for r in runs];wall=[r['end_to_end_sps'] for r in runs]
result={'migration_gate_passed':False,'learning_comparison_started':False,'reason_learning_comparison_skipped':'Deterministic dynamics, achievement semantics, world distribution and checkpoint continuation differ; a matched learning-per-hour comparison would be invalid.','features':parity['feature_port'],'encoder':encoder,'autoreset':reset,'deterministic_transitions':{'tested':len(parity['transition_cases']),'failed':len(failed),'failures':failed},'worlds':world,'resume':resume,'throughput':{'repeats':len(runs),'parameters':runs[0]['parameter_count'],'warm_median_sps':statistics.median(warm),'warm_range_sps':[min(warm),max(warm)],'process_median_sps':statistics.median(wall),'historical_jax_richer_map_sps':20475.673941601486,'ratio_to_historical_jax_richer_map':statistics.median(warm)/20475.673941601486,'interpretation':'Observed workload rates, not a validated speedup for the same MDP or algorithm.'},'reload_evaluations':timing.get('reload_evaluations',[]),'next_steps':['Preserve JAX as the production environment','Correct C world generation, resource floors, sleep behavior and achievement semantics; rerun paired state checks and broader stochastic/world tests','Implement and validate full optimizer, step counter and schedule resume','Benchmark corrected simulator with the validated map encoder','Only then run matched learning-per-hour and equal-step trials evaluated on identical original JAX worlds']}
(out/'summary.json').write_text(json.dumps(result,indent=2)+'\n')
t=result['throughput'];lines=['# PufferLib map-port validation','', '**Recommendation: keep the current JAX trainer. Migration checks failed.**','',f'The complete map/survival-input port ran at {t["warm_median_sps"]:,.0f} warmed steps/sec on one V100, median of {len(runs)} repeats, with {t["parameters"]:,} parameters. The historical richer-map JAX rate was 20,476 SPS. The observed ratio is {t["ratio_to_historical_jax_richer_map"]:.2f}x, but the environments and algorithms differ.','', '## Passed checks','',f'- Same-frame feature parity: {parity["feature_port"]["frames"]} frames; max error {parity["feature_port"]["max_absolute_error"]:.3g}.',f'- CUDA encoder forward/gradient reference: max error {encoder["max_absolute_error"]:.3g}; all 72 embedding entries receive gradients.','- Lava reward: terminal lava adds exactly −2, matching JAX.','- Timeout and lava autoreset clear terrain/history and preserve terminal reward.','- Training checkpoints have finite weights and reload for headless policy evaluation.','', '## Failed checks','', f'{len(failed)} of {len(parity["transition_cases"])} deterministic transition cases differed:','']
for r in failed:lines.append(f'- **{r["case"]}**: `{json.dumps(r["differences"])}`')
lines+=['','Across 128 independently generated maps per engine:','','| Mean tiles per map | C port | Original JAX |','|---|---:|---:|']
for name in ['water','stone','diamond','lava']:
 d=world['terrain_counts'][name];lines.append(f'| {name} | {d["c_mean_tiles"]:.2f} | {d["jax_mean_tiles"]:.2f} |')
lines+=['','These were distribution samples, not matching seeds. Source inspection confirms different generation rules; numerical seeds do not produce paired worlds.','', 'Upstream `train --base.load_model_path=...` ignored both a real checkpoint and a nonexistent path. All three 4,096-step test runs produced identical fresh weights. Checkpoint files contain weights only; they do not contain Muon momentum, step counters, or schedule state.','', 'The original local observation also has a small precision difference: JAX normalizes inventory/vitals in float16, C in float32.','','## Learning pilot','',result['reason_learning_comparison_skipped'],'No long learning-quality pilot or production migration was launched. Existing JAX training was preserved.','','## Next steps','']+[f'{i+1}. {s}' for i,s in enumerate(result['next_steps'])]
(out/'report.md').write_text('\n'.join(lines)+'\n')
paths=list((ROOT/'experiments/benchmarks/pufferlib_map').glob('*'))+[ROOT/'experiments/benchmarks/pufferlib_v100/run.py',ROOT/'third_party/PufferLib/puffer_map_v100']+list((ROOT/'third_party/PufferLib/build/map_validation').glob('*'))
(out/'source_hashes.json').write_text(json.dumps({str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths if p.is_file()},indent=2)+'\n')
print(json.dumps({'throughput':t,'failed_transition_cases':len(failed),'migration_gate_passed':False,'reload_evaluations':len(result['reload_evaluations'])},indent=2))
